solution:
from functools import wraps

def conta_chiamate(f):
    @wraps(f)
    def interna(*args, **kwargs):
        interna.chiamate += 1
        return f(*args, **kwargs)
    interna.chiamate = 0
    return interna

@conta_chiamate
def quadrato(x):
    return x * x

quadrato(2); quadrato(3)
print(quadrato.chiamate)
